// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.eclipse.rdf4j.common.order.StatementOrder;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.junit.jupiter.api.Test;

class LmdbNativeCostQuoteEdgeCaseTest {

	@Test
	void anInfiniteOutputEstimateCannotMakeUnknownWorkFreeForALimit() {
		LmdbNativeCandidate<String> unknown = LmdbNativeCandidate.of("unknown",
				LmdbNativeCostQuote.ofWork(LmdbNativeWork.UNKNOWN, Double.POSITIVE_INFINITY), () -> "unknown");
		LmdbNativeCandidate<String> finite = LmdbNativeCandidate.of("finite",
				LmdbNativeCostQuote.streaming(LmdbNativeCostVector.point(Feature.SCANNED_ROW, 100D), 100D),
				() -> "finite");
		LmdbNativeSelector.Ranking ranked = LmdbNativeSelector.rank(List.of(unknown, finite),
				LmdbNativeStaticPrior.DEFAULT, 1D, 4);
		assertThat(ranked.nanos()[0].known()).isFalse();
		assertThat(ranked.winner()).isEqualTo(1);
	}

	@Test
	void finiteSlicesPreserveUnknownWorkAndZeroSlicesKeepStartup() {
		LmdbNativeCostQuote quote = new LmdbNativeCostQuote(LmdbNativeCostVector.point(Feature.OPEN, 1D),
				LmdbNativeCostVectors.unbounded(), 1_000D, false, false);
		assertThat(quote.forSlice(1D).high(Feature.SCANNED_ROW))
				.isGreaterThanOrEqualTo(LmdbNativeCostQuote.UNBOUNDED_COUNT);
		assertThat(quote.forSlice(0D).high(Feature.SCANNED_ROW)).isZero();
		assertThat(quote.forSlice(0D).high(Feature.OPEN)).isEqualTo(1D);
	}

	@Test
	void aFixedDatasetChargesASeekForEveryUnboundContext() {
		PatternPlan pattern = pattern(new ContextConstraint(new long[] { 41L, 42L, 43L }));
		LmdbNativeCostVector vector = LmdbNativeCostVectors.pattern(pattern, null, 0L);
		assertThat(vector.low(Feature.INDEX_SEEK)).as("each fixed graph needs its own index seek")
				.isEqualTo(3D);
	}

	@Test
	void aBoundContextNeedsOnlyOneSeekWithinAFixedDataset() {
		PatternPlan pattern = pattern(new ContextConstraint(new long[] { 41L, 42L, 43L }));
		LmdbNativeCostVector vector = LmdbNativeCostVectors.pattern(pattern, null, 1L << 2);
		assertThat(vector.low(Feature.INDEX_SEEK)).isEqualTo(1D);
	}

	private static PatternPlan pattern(ContextConstraint contexts) {
		int[][] prefixes = new int[StatementOrder.values().length + 1][16];
		for (int[] row : prefixes) {
			for (int mask = 0; mask < row.length; mask++) {
				row[mask] = mask;
			}
		}
		NativeLmdbQuerySource.IndexAccessProfile profile = new NativeLmdbQuerySource.IndexAccessProfile(
				100L, 1, prefixes, false, -1L, -1L, -1L);
		return new PatternPlan(Term.slot(0), Term.constant(10L), Term.slot(1), Term.slot(2), contexts,
				true, null, "", null, 100D, profile);
	}
}
